curl -s 'http://localhost:16686/jaeger/ui/api/traces?service=product-catalog&limit=30&lookback=2h' | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('num traces', len(d.get('data',[])))
found=0
for t in d.get('data',[]):
    for s in t['spans']:
        if s.get('operationName')=='oteldemo.ProductCatalogService/GetProduct':
            tags={x['key']:x['value'] for x in s.get('tags',[])}
            if tags.get('otel.status_code')=='ERROR' or tags.get('rpc.grpc.status_code') not in (0,None):
                found+=1
                print(t['traceID'], tags.get('rpc.grpc.status_code'), tags.get('otel.status_code'))
                for l in s.get('logs',[]):
                    print('  log:', {f['key']:f['value'] for f in l['fields']})
print('found errors', found)
"
